Task: Push the orange puck so that its centre ends up inside the green circle. The puck is too wide to grasp.

Skill code (numbered):
  1| # skill module
  2| import math
  3| import numpy as np
  4| 
  5| # ---------- configuration ----------
  6| MAX_PUSH_ATTEMPTS = 8          # total pushes we will try
  7| MAX_PUSH_PER_STEP = 0.010      # 1.0 cm per step – fits the narrow corridor
  8| CLEARANCE_ABOVE = 0.025        # 2.5 cm clearance to avoid side collisions
  9| MIN_APPROACH_Z = 0.014         # lowest safe height
 10| SLOW_SPEED = 0.05              # m/s, used everywhere
 11| 
 12| def run(robot):
 13|     # ---------- 1. perception ----------
 14|     obs = robot.observe()
 15|     puck = obs["objects"]["puck"]
 16|     target = obs["fixtures"]["target"]
 17|     puck_pos = np.array(puck["pos"], dtype=float)          # centre of puck
 18|     target_pos = np.array(target["pos"][:2], dtype=float)  # (x, y) of zone centre
 19|     target_radius = target["radius"]
 20| 
 21|     # If puck already inside the target, we are done
 22|     if np.linalg.norm(puck_pos[:2] - target_pos) < target_radius:
 23|         return True
 24| 
 25|     # ---------- 2. approach from above ----------
 26|     # Compute a small offset toward the target to avoid side contacts
 27|     delta_xy = target_pos - puck_pos[:2]
 28|     remaining_xy = np.linalg.norm(delta_xy)
 29|     if remaining_xy > 1e-6:
 30|         offset_dir = delta_xy / remaining_xy
 31|         offset = 0.02 * offset_dir               # ~2 cm offset, safe margin
 32|     else:
 33|         offset_dir = np.array([1.0, 0.0])
 34|         offset = np.array([0.02, 0.0])
 35| 
 36|     approach_xy = puck_pos[:2] + offset
 37|     approach_z = puck_pos[2] + CLEARANCE_ABOVE
 38|     # Clamp to the safe workspace
 39|     approach_z = max(approach_z, MIN_APPROACH_Z)
 40|     approach_z = min(approach_z, 0.26)
 41| 
 42|     # Try to move to the approach pose; if blocked, raise height a bit and retry
 43|     for retry in range(2):
 44|         try:
 45|             robot.move_to(approach_xy[0], approach_xy[1], approach_z, speed=SLOW_SPEED)
 46|             break
 47|         except Exception:
 48|             # first lift step
 49|             approach_z = min(approach_z + 0.005, 0.26)
 50|             # second lift step after the first retry (extra +0.005 m)
 51|             if retry == 0:
 52|                 approach_z = min(approach_z + 0.005, 0.26)
 53|             robot.move_to(approach_xy[0], approach_xy[1], approach_z, speed=SLOW_SPEED)
 54| 
 55|     # ---------- 3. descend to touch the puck top ----------
 56|     # Fingertips sit ~1.25 cm below the tool point; lower by that amount
 57|     for _ in range(2):
 58|         try:
 59|             robot.move_by(dz=-0.0125, speed=SLOW_SPEED)
 60|             break
 61|         except Exception:
 62|             # Lift a little and try the descent again
 63|             robot.move_by(dz=0.005, speed=SLOW_SPEED)
 64|             robot.move_by(dz=-0.0125, speed=SLOW_SPEED)
 65| 
 66|     # Ensure we are a bit higher to avoid collision on the next descent
 67|     approach_z = min(approach_z + 0.01, 0.26)
 68| 
 69|     # ---------- 4. iterative pushing ----------
 70|     for _ in range(MAX_PUSH_ATTEMPTS):
 71|         # Re‑observe to get the current puck pose (it may have moved)
 72|         obs = robot.observe()
 73|         puck = obs["objects"]["puck"]
 74|         puck_pos = np.array(puck["pos"], dtype=float)
 75|         delta = target_pos - puck_pos[:2]
 76|         dist = np.linalg.norm(delta)
 77| 
 78|         # Success if we are already inside the target radius
 79|         if dist < target_radius:
 80|             break
 81| 
 82|         # Determine a safe push step (never exceed what remains)
 83|         push_step = min(MAX_PUSH_PER_STEP, dist)
 84|         if push_step <= 0:
 85|             break
 86|         direction = delta / dist
 87| 
 88|         # Attempt the push; on blockage we lift, re‑observe and continue
 89|         try:
 90|             robot.move_by(
 91|                 dx=direction[0] * push_step,
 92|                 dy=direction[1] * push_step,
 93|                 speed=SLOW_SPEED
 94|             )
 95|         except Exception:
 96|             # Lift back to approach height to reset the gripper
 97|             try:
 98|                 robot.move_to(puck_pos[0], puck_pos[1], approach_z, speed=SLOW_SPEED)
 99|             except Exception:
100|                 pass
101|             continue   # try the next push attempt
102| 
103|         # After a successful push, lift back up to the safe approach height
104|         try:
105|             robot.move_to(puck_pos[0], puck_pos[1], approach_z, speed=SLOW_SPEED)
106|         except Exception:
107|             pass
108| 
109|     # ---------- 5. final verification ----------
110|     final_obs = robot.observe()
111|     final_puck = np.array(final_obs["objects"]["puck"]["pos"], dtype=float)
112|     final_dist = np.linalg.norm(final_puck[:2] - target_pos)
113| 
114|     return final_dist < target_radius

